-- =====================================================================
-- SGE Inventory - Schema Sistem Manajemen Barang
-- Database : PostgreSQL 18
-- =====================================================================
-- Catatan perbedaan dari versi MariaDB sebelumnya:
-- * ID memakai BIGINT GENERATED BY DEFAULT AS IDENTITY (pengganti AUTO_INCREMENT).
-- * Postgres tidak punya UNSIGNED, jadi angka >= 0 dijaga dengan CHECK.
-- * ENUM diganti VARCHAR + CHECK (nilai baru cukup ubah CHECK-nya).
-- * Waktu memakai TIMESTAMPTZ (waktu + zona waktu).
-- * Tidak ada "ON UPDATE CURRENT_TIMESTAMP"; updated_at diisi oleh GORM saat Update.
-- * Index dibuat dengan CREATE INDEX terpisah (bukan KEY di dalam CREATE TABLE).

-- ---------------------------------------------------------------------
-- lembaga : Lembaga / Divisi / Unit Kerja (BEM, HIMA, UKM X, ...)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lembaga (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(150) NOT NULL,
    description TEXT         NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at  TIMESTAMPTZ  NULL,
    CONSTRAINT uq_lembaga_name UNIQUE (name)
);
CREATE INDEX IF NOT EXISTS idx_lembaga_deleted_at ON lembaga (deleted_at);

-- ---------------------------------------------------------------------
-- users : pengguna sistem (tidak terikat lembaga; lembaga dipilih saat
-- mengajukan peminjaman, lihat borrowings.lembaga_id)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name     VARCHAR(255) NOT NULL,
    email         VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    contact       VARCHAR(50)  NULL,
    role          VARCHAR(20)  NOT NULL DEFAULT 'USER',
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at    TIMESTAMPTZ  NULL,
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT chk_users_role CHECK (role IN ('ADMIN', 'USER'))
);
CREATE INDEX IF NOT EXISTS idx_users_role ON users (role);
CREATE INDEX IF NOT EXISTS idx_users_deleted_at ON users (deleted_at);

-- ---------------------------------------------------------------------
-- items : master barang / inventaris
-- total_quantity     : jumlah barang yang dimiliki (diatur admin)
-- available_quantity : sisa yang bisa dipinjam (berkurang saat pengajuan
--                      di-ACC, bertambah saat barang dikembalikan)
-- Status tidak disimpan; dihitung dari available_quantity
-- (> 0 = TERSEDIA, 0 = HABIS).
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS items (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name               VARCHAR(255) NOT NULL,
    total_quantity     INTEGER      NOT NULL DEFAULT 0,
    available_quantity INTEGER      NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at         TIMESTAMPTZ  NULL,
    CONSTRAINT chk_items_total_non_negative CHECK (total_quantity >= 0),
    CONSTRAINT chk_items_available_non_negative CHECK (available_quantity >= 0),
    CONSTRAINT chk_items_available_lte_total CHECK (available_quantity <= total_quantity)
);
CREATE INDEX IF NOT EXISTS idx_items_available ON items (available_quantity);
CREATE INDEX IF NOT EXISTS idx_items_deleted_at ON items (deleted_at);

-- ---------------------------------------------------------------------
-- borrowings : header pengajuan peminjaman
-- reviewed_by NULL + status REJECTED = ditolak otomatis oleh sistem
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS borrowings (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT       NOT NULL,
    lembaga_id          BIGINT       NOT NULL,
    status              VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    purpose             VARCHAR(500) NULL,
    borrow_date         DATE         NOT NULL,
    planned_return_date DATE         NOT NULL,
    actual_return_date  DATE         NULL,
    reviewed_by         BIGINT       NULL,
    reviewed_at         TIMESTAMPTZ  NULL,
    rejection_reason    VARCHAR(500) NULL,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_borrowings_status CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'RETURNED')),
    CONSTRAINT chk_borrowings_dates CHECK (planned_return_date >= borrow_date),
    CONSTRAINT fk_borrowings_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_borrowings_lembaga FOREIGN KEY (lembaga_id)
        REFERENCES lembaga (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_borrowings_reviewer FOREIGN KEY (reviewed_by)
        REFERENCES users (id) ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_borrowings_user_status ON borrowings (user_id, status);
CREATE INDEX IF NOT EXISTS idx_borrowings_lembaga_id ON borrowings (lembaga_id);
CREATE INDEX IF NOT EXISTS idx_borrowings_status_created ON borrowings (status, created_at);
CREATE INDEX IF NOT EXISTS idx_borrowings_reviewed_by ON borrowings (reviewed_by);

-- ---------------------------------------------------------------------
-- borrowing_items : detail barang pada tiap pengajuan (multi-item)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS borrowing_items (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    borrowing_id BIGINT      NOT NULL,
    item_id      BIGINT      NOT NULL,
    quantity     INTEGER     NOT NULL,
    status_item  VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    created_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_borrowing_items_borrowing_item UNIQUE (borrowing_id, item_id),
    CONSTRAINT chk_borrowing_items_status CHECK (status_item IN ('PENDING', 'APPROVED', 'REJECTED', 'RETURNED')),
    CONSTRAINT chk_borrowing_items_quantity CHECK (quantity > 0),
    CONSTRAINT fk_borrowing_items_borrowing FOREIGN KEY (borrowing_id)
        REFERENCES borrowings (id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_borrowing_items_item FOREIGN KEY (item_id)
        REFERENCES items (id) ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_borrowing_items_item_status ON borrowing_items (item_id, status_item);

-- ---------------------------------------------------------------------
-- item_consignments : penitipan barang milik user ke organisasi
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS item_consignments (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_user_id   BIGINT       NOT NULL,
    item_name       VARCHAR(255) NOT NULL,
    quantity        INTEGER      NOT NULL,
    start_date      DATE         NOT NULL,
    end_date        DATE         NOT NULL,
    status          VARCHAR(20)  NOT NULL DEFAULT 'DITITIPKAN',
    condition_notes TEXT         NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_consignments_status CHECK (status IN ('DITITIPKAN', 'DIAMBIL', 'EXPIRED')),
    CONSTRAINT chk_consignments_quantity CHECK (quantity > 0),
    CONSTRAINT chk_consignments_dates CHECK (end_date >= start_date),
    CONSTRAINT fk_consignments_owner FOREIGN KEY (owner_user_id)
        REFERENCES users (id) ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_consignments_owner ON item_consignments (owner_user_id);
CREATE INDEX IF NOT EXISTS idx_consignments_status_end ON item_consignments (status, end_date);

